  // ── Messages from the server ──
  "The server took too long to respond. Please try again.": ["सर्वर ने जवाब देने में बहुत समय लिया। कृपया फिर से कोशिश करें।", "सर्व्हरने उत्तर द्यायला खूप वेळ घेतला. कृपया पुन्हा प्रयत्न करा."],
  "Too many attempts. Please wait a few minutes and try again.": ["बहुत ज़्यादा कोशिशें हो गईं। कृपया कुछ मिनट रुककर फिर से कोशिश करें।", "खूप जास्त प्रयत्न झाले. कृपया काही मिनिटे थांबून पुन्हा प्रयत्न करा."],
  "Something went wrong on our side. Please try again shortly.": ["हमारी तरफ़ से कुछ गड़बड़ हो गई। कृपया थोड़ी देर में फिर से कोशिश करें।", "आमच्या बाजूने काहीतरी चुकले. कृपया थोड्या वेळाने पुन्हा प्रयत्न करा."],
  "Too many authentication attempts. Please wait 15 minutes before trying again.": ["लॉग इन की बहुत ज़्यादा कोशिशें हो गईं। कृपया 15 मिनट बाद फिर से कोशिश करें।", "लॉग इनचे खूप जास्त प्रयत्न झाले. कृपया 15 मिनिटांनी पुन्हा प्रयत्न करा."],
  "Too many requests. Please try again later.": ["बहुत ज़्यादा अनुरोध हो गए। कृपया बाद में फिर से कोशिश करें।", "खूप जास्त विनंत्या झाल्या. कृपया नंतर पुन्हा प्रयत्न करा."],
  "Session expired. Please log in again.": ["सत्र समाप्त हो गया। कृपया फिर से लॉग इन करें।", "सत्र संपले आहे. कृपया पुन्हा लॉग इन करा."],
  "Session has been terminated. Please log in again.": ["सत्र बंद कर दिया गया है। कृपया फिर से लॉग इन करें।", "सत्र बंद करण्यात आले आहे. कृपया पुन्हा लॉग इन करा."],

