  "Medical & medicines": ["चिकित्सा और दवाएँ", "वैद्यकीय व औषधे"],
  "Conditions and medicines that block absorption.": ["बीमारियाँ और दवाएँ जो अवशोषण रोकती हैं।", "शोषणात अडथळा आणणारे आजार आणि औषधे."],
  "Lifestyle": ["जीवनशैली", "जीवनशैली"],
  "Sleep, stress, alcohol and daily routine.": ["नींद, तनाव, शराब और दिनचर्या।", "झोप, ताण, मद्य आणि दिनचर्या."],
  "Physical signs": ["शारीरिक संकेत", "शारीरिक लक्षणे"],
